head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > checkcomboboxUseDrag]<br/>inputType='checkcombobox' 인 Column 의 아이템 리스트창에서 마우스로 드래그하여 아이템을 선택/해제할지 설정합니다.",
    "validation" : [
        "true 설정 시, 아이템 리스트창을 마우스로 드래그하여 해당 영역의 아이템들을 선택합니다.",
        "true 설정 시, Shift 키를 누른 상태로 마우스를 드래그하면 해당 영역의 선택된 아이템들을 해제합니다.",
        "false 설정 시, 마우스로 드래그하여 아이템들을 선택/해제할 수 없습니다.",
        "미설정 시, 마우스로 드래그하여 아이템들을 선택/해제할 수 없습니다.",
        "false 설정 시, 마우스로 클릭하여 아이템을 선택/해제할 수 있습니다.",
        "Column 의 아이템이 GridViewItemSet 으로 정의된 경우 GridView 팝업창이 표시되므로 checkcomboboxUseDrag 속성이 무시됩니다.",
        "마우스로 드래그하여 아이템 리스트창의 스크롤을 이동할 수 없습니다.",
        "마우스로 드래그하여 한 개 아이템의 선택 상태를 변경할 수 없습니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (true / 기본 아이템)
    con_checkcomboboxUseDrag.setValue("2");
    con_itemDefinition.setValue("item");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 1월 ~ 12월 (value 1 ~ 12), 리스트창 기본 표시 행 수(5) 보다 많아 세로 스크롤 표시
scwin.itemCount = 12;
scwin.rowData = [
    { "name" : "선택 없음", "month" : "" },
    { "name" : "1월 ~ 5월 선택", "month" : "1 2 3 4 5" }
];



// comp 생성
//  - name  : 초기 선택 상태 설명 Column
//  - month : 검증 대상 Body Column (inputType=checkcombobox, 아이템 1월 ~ 12월)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_month !== 'undefined' && dlt_month) {
        $p.data.remove("dlt_month");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cUseDrag = con_checkcomboboxUseDrag.getText();
    let cItemDefinition = con_itemDefinition.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] month 셀 더블클릭으로 아이템 리스트창 열기 -> 아이템 위에서 드래그(또는 Shift+드래그, 클릭) -> 셀 밖 클릭으로 편집 종료\n[확인] 편집 종료 후 출력되는 선택값\n[스크롤] 0행에서 1월부터 리스트창 아래 밖까지 드래그 -> 리스트창이 스크롤되지 않고 리스트창에 보이는 아이템까지만 선택\n[한 개 아이템] 한 아이템 안에서만 드래그 -> 선택 상태 그대로"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList (선택값 구분자는 기본 공백)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="month" name="month" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowData, false);

    // 아이템 정의
    let strItems = '<w2:choices>';
    if (cItemDefinition === "gridViewItemset") {
        // GridViewItemSet : checkbox item 은 dataList 첫 컬럼(chk) 을 참조 (checkColumn=0)
        let strItemDlt = '';
        strItemDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_month" baseNode="list" repeatNode="map">';
        strItemDlt += '<w2:columnInfo>';
        strItemDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
        strItemDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
        strItemDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
        strItemDlt += '</w2:columnInfo>';
        strItemDlt += '<w2:data use="true"></w2:data>';
        strItemDlt += '</w2:dataList>';
        $p.data.create(strItemDlt);
        let arrItem = [];
        for (let i = 1; i <= scwin.itemCount; i++) {
            arrItem.push({ "chk" : "0", "value" : String(i), "label" : i + "월" });
        }
        dlt_month.setJSON(arrItem, false);

        strItems += '<w2:gridViewItemset nodeset="data:dlt_month" label="label" value="value" checkColumn="0">';
        strItems += '<w2:item header="선택" inputType="checkbox" ref="chk"></w2:item>';
        strItems += '<w2:item header="value" ref="value"></w2:item>';
        strItems += '<w2:item header="label" ref="label"></w2:item>';
        strItems += '</w2:gridViewItemset>';
    } else {
        for (let i = 1; i <= scwin.itemCount; i++) {
            strItems += '<w2:item><w2:label>' + i + '월</w2:label><w2:value>' + i + '</w2:value></w2:item>';
        }
    }
    strItems += '</w2:choices>';

    // month Column 속성
    let attrMonth = ' inputType="checkcombobox"';
    attrMonth += (cUseDrag === '') ? '' : ' checkcomboboxUseDrag="' + cUseDrag + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:150px;" ev:oneditend="scwin.target1_oneditend">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="초기 선택 상태"></w2:column>';
    strTarget += '<w2:column width="360" style="" inputType="text" id="column2" value="month (checkcombobox)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="360" style="text-align:left;" id="month" value=""' + attrMonth + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 ~ 8 : 편집 종료 후 해당 행 선택값
scwin.target1_oneditend = function (rowIndex, colIndex) {
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("편집 종료 후 " + rowIndex + "행 선택값 : '" + dlt_bind.getCellData(rowIndex, "month") + "'");
    }, 100);
}
